steps.prompt:
Write .gitlab-ci.yml:

- stages: test, build, deploy (in that order)

- job 'unit' in stage test: image python:3.12; script runs 'pip install -r requirements.txt' then 'pytest';
  a cache whose key.files lists requirements.txt and whose paths list .cache/pip

- job 'image' in stage build: image gcr.io/kaniko-project/executor:debug;
  script contains a line starting with '/kaniko/executor' that uses --destination $CI_REGISTRY_IMAGE:$CI_COMMIT_SHORT_SHA;
  rules: one rule, if: $CI_COMMIT_BRANCH == "main"

- job 'production' in stage deploy: script runs './deploy.sh $CI_COMMIT_SHORT_SHA';
  environment name production; needs the job image;
  rules: one rule, if: $CI_COMMIT_BRANCH == "main" with when: manual
